import type {
  AuthenticatorPort,
  AuthnRequest,
  AuthnResult,
  Principal,
} from '@netscript/service/auth';
import { betterAuth, type BetterAuthOptions } from 'better-auth';
import { prismaAdapter } from 'better-auth/adapters/prisma';

const AUTH_PRISMA_MODEL_NAMES = {
  user: 'authUser',
  session: 'authSession',
  account: 'authAccount',
  verification: 'authVerification',
} as const;

/** Prisma providers supported by better-auth's first-party Prisma adapter. */
export type BetterAuthPrismaProvider =
  | 'sqlite'
  | 'cockroachdb'
  | 'mysql'
  | 'postgresql'
  | 'sqlserver'
  | 'mongodb';

/** Structural Prisma client accepted by better-auth's first-party Prisma adapter. */
export type BetterAuthPrismaClient = object;

/** Options for constructing a better-auth instance backed by consumer-owned Prisma. */
export interface NetscriptBetterAuthOptions {
  /** Consumer-owned Prisma client. */
  readonly prisma: BetterAuthPrismaClient;
  /** Prisma provider name passed to better-auth's first-party Prisma adapter. */
  readonly provider: BetterAuthPrismaProvider;
  /** Enable better-auth Prisma adapter debug logs. */
  readonly debugLogs?: boolean;
  /** Use plural better-auth table names. */
  readonly usePlural?: boolean;
  /** Enable better-auth adapter transactions when supported by the provider. */
  readonly transaction?: boolean;
  /** better-auth application name. */
  readonly appName?: string;
  /** better-auth base URL. */
  readonly baseURL?: string;
  /** better-auth base path. */
  readonly basePath?: string;
  /** better-auth secret. */
  readonly secret?: string;
  /** Origins trusted by better-auth. */
  readonly trustedOrigins?: string[];
  /** better-auth advanced runtime options used by NetScript tests and local adapters. */
  readonly advanced?: {
    readonly disableCSRFCheck?: boolean;
  };
  /** better-auth telemetry options. */
  readonly telemetry?: {
    readonly enabled?: boolean;
    readonly debug?: boolean;
  };
  /**
   * better-auth server plugins.
   *
   * Table-backed plugins such as organization, twoFactor, admin, and apiKey
   * require their better-auth schema to be generated and migrated before they
   * are runnable. Stateless plugins such as bearer and jwt can run through this
   * passthrough alone.
   */
  readonly plugins?: BetterAuthOptions['plugins'];
  /**
   * Additional better-auth options not surfaced directly by NetScript.
   *
   * NetScript owns `database` through the Prisma adapter, and `plugins` should
   * use the dedicated top-level field.
   */
  readonly betterAuthOptions?: Omit<BetterAuthOptions, 'database' | 'plugins'>;
}

/** Session shape returned by `auth.api.getSession`. */
export interface BetterAuthSessionPayload {
  /** better-auth session record. */
  readonly session: {
    readonly id: string;
    readonly userId?: string;
    readonly activeOrganizationId?: string | null;
    readonly activeOrganizationRole?: string | null;
    readonly activeOrganizationRoles?: readonly string[] | null;
    readonly activeOrganizationPermissions?: readonly string[] | null;
    readonly [key: string]: unknown;
  };
  /** better-auth user record. */
  readonly user: {
    readonly id: string;
    readonly role?: string | null;
    readonly roles?: readonly string[] | null;
    readonly [key: string]: unknown;
  };
}

/** Minimal better-auth server instance consumed by this package. */
export interface BetterAuthInstance {
  /** better-auth Fetch handler for `/api/auth/**` routes. */
  readonly handler: (request: Request) => Promise<Response>;
  /** better-auth session API consumed by NetScript adapters. */
  readonly api: {
    readonly getSession: (
      input: BetterAuthGetSessionInput,
    ) => Promise<BetterAuthSessionLookupResponse>;
    /** Revokes every session of the user whose session the request headers carry. */
    readonly revokeSessions: (
      input: BetterAuthRevokeSessionsInput,
    ) => Promise<unknown>;
  };
}

/** Input accepted by better-auth's `api.revokeSessions` method. */
export type BetterAuthRevokeSessionsInput = Readonly<{
  headers: Headers;
}>;

/** Input accepted by better-auth's `api.getSession` method. */
export type BetterAuthGetSessionInput = Readonly<{
  headers: Headers;
  returnHeaders?: boolean;
  /** better-auth query flags; NetScript always sets `disableCookieCache`. */
  query?: Readonly<{ disableCookieCache?: boolean }>;
}>;

/**
 * Reads the request's session from better-auth's server-side store, never from the signed
 * `session_data` cookie cache.
 *
 * better-auth's own guidance for sensitive reads is to pass `disableCookieCache` so a revoked but
 * still-cached session cannot authorize anything; NetScript applies it to every lookup, so a
 * revocation (single or subject-wide) takes effect on the next request instead of after the cache
 * cookie's `maxAge`.
 */
export function getAuthoritativeSession(
  auth: BetterAuthInstance,
  headers: Headers,
): Promise<BetterAuthSessionLookupResponse> {
  return auth.api.getSession({
    headers,
    returnHeaders: true,
    query: { disableCookieCache: true },
  });
}

/** Session lookup response shape consumed by NetScript better-auth adapters. */
export type BetterAuthSessionLookupResponse =
  | BetterAuthSessionPayload
  | null
  | {
    readonly headers?: Headers;
    readonly response: BetterAuthSessionPayload | null;
  };

/** Options for creating a better-auth-backed NetScript authenticator. */
export interface BetterAuthAuthenticatorOptions {
  /** Configured better-auth server instance. */
  readonly auth: BetterAuthInstance;
}

/** Creates a better-auth server instance backed by better-auth's Prisma adapter.
 *
 * @param options - Consumer Prisma client, provider, and better-auth options.
 * @returns A better-auth instance suitable for `createBetterAuthAuthenticator`.
 *
 * @example
 * ```ts
 * import { type BetterAuthPrismaClient, createNetscriptBetterAuth } from '@netscript/auth-better-auth';
 * import { organization } from 'better-auth/plugins';
 *
 * declare const prisma: BetterAuthPrismaClient;
 *
 * const auth = createNetscriptBetterAuth({
 *   prisma,
 *   provider: 'postgresql',
 *   secret: Deno.env.get('BETTER_AUTH_SECRET')!,
 *   plugins: [organization()],
 * });
 * ```
 */
