      revocations,
      workos,
      Date.now,
      options.workosRevocationWorkerOptions,
    );
    const backend = createWorkosBackend({
      revocations: {
        ...revocations,
        async revokeSubject(subject, revokedAt) {
          const job = await revocations.revokeSubject(subject, revokedAt);
          background.wake();
          return job;
        },
