      background,
    });
  }

  return createBetterAuthBackend({
    auth: createNetscriptBetterAuth({
      prisma: options.dbClient ?? {},
      provider: betterAuthPrismaProvider(env.DB_PROVIDER),
      secret: requiredEnv(env, 'BETTER_AUTH_SECRET'),
