}

async function createWorkosSdk(env: Readonly<Record<string, string | undefined>>) {
  const { WorkOS } = await import('@workos-inc/node');
  return new WorkOS(requiredEnv(env, 'WORKOS_API_KEY'), {
    clientId: requiredEnv(env, 'WORKOS_CLIENT_ID'),
  });
}

function positiveMilliseconds(value: string | undefined, fallback: number): number {
  const parsed = value === undefined ? fallback : Number(value);
  if (!Number.isSafeInteger(parsed) || parsed <= 0) {
    throw new RangeError('WorkOS lifetime and skew must be positive integer milliseconds.');
  }
  return parsed;
}

function createWorkosCookieSession(
  session: WorkosSdkCookieSession,
): WorkosCookieSession {
  return {
    async authenticate(): Promise<WorkosSessionAuthenticationResult> {
      return normalizeWorkosAuthentication(await session.authenticate());
    },
    async refresh(options): Promise<WorkosSessionRefreshResult> {
      return normalizeWorkosRefresh(await session.refresh(options));
    },
  };
}

function normalizeWorkosAuthentication(
  result: WorkosSdkAuthenticationResult,
): WorkosSessionAuthenticationResult {
  if (!result.authenticated) {
    return result;
  }
  return {
    ...result,
    user: { id: result.user.id },
  };
}

function normalizeWorkosRefresh(
  result: WorkosSdkRefreshResult,
): WorkosSessionRefreshResult {
  if (!result.authenticated) {
    return result;
  }
  return {
    ...result,
    user: { id: result.user.id },
  };
}

function requiredEnv(env: Readonly<Record<string, string | undefined>>, name: string): string {
  const value = env[name];
  if (!value) {
    throw new Error(`${name} is required for the selected auth backend.`);
  }
  return value;
}

function betterAuthPrismaProvider(value: string | undefined) {
  if (value === 'postgres') return 'postgresql';
  if (
    value === 'sqlite' || value === 'mysql' || value === 'mongodb' || value === 'sqlserver' ||
    value === 'cockroachdb' || value === 'postgresql'
  ) {
    return value;
  }
  return 'postgresql';
}

function resolveKvOAuthProviderEnv(
  env: Readonly<Record<string, string | undefined>>,
): Readonly<{
  clientId: string;
  redirectUri: string;
  authorizationEndpoint?: string;
  tokenEndpoint?: string;
}> {
  return {
    clientId: env.NETSCRIPT_AUTH_CLIENT_ID ?? 'netscript-auth-local',
    redirectUri: env.NETSCRIPT_AUTH_REDIRECT_URI ??
      `${localAuthOrigin(env)}/api/v1/auth/callback`,
    authorizationEndpoint: env.NETSCRIPT_AUTH_AUTHORIZATION_ENDPOINT ??
      (env.NETSCRIPT_AUTH_ISSUER
        ? undefined
        : `${localAuthOrigin(env)}/v1/auth/signin/not-configured`),
    tokenEndpoint: env.NETSCRIPT_AUTH_TOKEN_ENDPOINT ??
      (env.NETSCRIPT_AUTH_ISSUER
        ? undefined
        : `${localAuthOrigin(env)}/v1/auth/token/not-configured`),
  };
}

function localAuthOrigin(env: Readonly<Record<string, string | undefined>>): string {
  return `http://localhost:${requiredEnv(env, 'PORT')}`; // aspire-host-port-ok: own origin from Aspire-allocated PORT
}

function resolveKvOAuthKey(env: Readonly<Record<string, string | undefined>>): ArrayBuffer {
  const configured = requiredEnv(env, 'NETSCRIPT_AUTH_KV_OAUTH_KEY');
  const normalized = configured.replaceAll('-', '+').replaceAll('_', '/');
  const padded = normalized.padEnd(Math.ceil(normalized.length / 4) * 4, '=');
  const bytes = Uint8Array.from(atob(padded), (char) => char.charCodeAt(0));
  if (bytes.byteLength !== 32) {
    throw new Error('NETSCRIPT_AUTH_KV_OAUTH_KEY must decode to exactly 32 bytes.');
  }
  return copyArrayBuffer(bytes);
}

function copyArrayBuffer(bytes: Uint8Array): ArrayBuffer {
  const buffer = new ArrayBuffer(bytes.byteLength);
  new Uint8Array(buffer).set(bytes);
  return buffer;
}

/** Creates a test-friendly kv-oauth registry using an in-memory KV adapter. */
export async function createInMemoryKvOAuthRegistry(
  options: Omit<CreateAuthServiceBackendRegistryOptions, 'kv'> = {},
): Promise<ResolvedAuthBackendRegistry> {
  return await createAuthServiceBackendRegistry({
    ...options,
    kv: new MemoryKvAdapter(),
    env: {
      NETSCRIPT_AUTH_BACKEND: 'kv-oauth',
      NETSCRIPT_AUTH_CLIENT_ID: 'client_test',
      NETSCRIPT_AUTH_CLIENT_SECRET: 'secret_test',
      NETSCRIPT_AUTH_AUTHORIZATION_ENDPOINT: 'https://issuer.example.test/oauth/authorize',
      NETSCRIPT_AUTH_TOKEN_ENDPOINT: 'https://issuer.example.test/oauth/token',
      NETSCRIPT_AUTH_REDIRECT_URI: 'https://app.example.test/api/v1/auth/callback',
      NETSCRIPT_AUTH_KV_OAUTH_KEY: 'BwcHBwcHBwcHBwcHBwcHBwcHBwcHBwcHBwcHBwcHBwc=',
      NETSCRIPT_AUTH_ALLOW_INSECURE_HTTP_REQUESTS: 'true',
      ...(options.env ?? {}),
    },
  });
}


