        const entries = await Promise.all(keys.map((key) => this.get<T>(key)));
        if (options.signal?.aborted) return;
        yield keys.map((key, index) => ({
          key,
          timestamp: new Date(),
          type: entries[index] ? 'set' : 'delete',
          value: entries[index]?.value ?? null,
          versionstamp: entries[index]?.versionstamp ?? null,
          initial: true,
        }));
      }
      while (!options?.signal?.aborted && !this.closed) {
        if (eventQueue.length === 0) {
          let timeoutId: ReturnType<typeof setTimeout> | undefined;
          await Promise.race([
            new Promise<void>((resolve) => {
              resolveNext = resolve;
            }),
            new Promise<void>((resolve) => {
              timeoutId = setTimeout(resolve, 1000);
            }),
          ]);
          if (timeoutId !== undefined) {
            clearTimeout(timeoutId);
          }
        }

        if (eventQueue.length === 0) {
          continue;
        }

        const events = [...eventQueue];
        eventQueue.length = 0;

        if (options?.debounce && !(await this.debounce(options.debounce, options.signal))) {
          break;
        }

        yield events;
      }
    } finally {
      options?.signal?.removeEventListener('abort', onAbort);
      for (const key of keys) {
        const keyStr = keyToString(key);
        const keyWatchers = this.watchers.get(keyStr);
        if (!keyWatchers) {
          continue;
        }

        keyWatchers.delete(handler);
        if (keyWatchers.size === 0) {
          this.watchers.delete(keyStr);
        }
      }
    }
  }

  /**
   * Watch a key prefix, including newly created keys.
   *
   * @param prefix - Prefix to observe
   * @param options - Prefix watch options
   * @returns Async iterable of individual events
   */
  async *watchPrefix<T = unknown>(
    prefix: KvKey,
    options?: WatchPrefixOptions,
  ): AsyncIterable<WatchEvent<T>> {
    this.assertOpen();

    if (!options?.skipInitial) {
      for await (const entry of this.list<T>({ prefix })) {
        yield {
          key: entry.key,
          timestamp: new Date(),
          type: 'set',
          value: entry.value,
          versionstamp: entry.versionstamp,
        };
      }
    }

    const prefixStr = keyToString(prefix);
    const eventQueue: WatchEvent<T>[] = [];
    let resolveNext: (() => void) | null = null;

    const handler = (event: WatchEvent): void => {
      eventQueue.push(event as WatchEvent<T>);
      resolveNext?.();
      resolveNext = null;
    };

    if (!this.prefixWatchers.has(prefixStr)) {
      this.prefixWatchers.set(prefixStr, { prefix, handlers: new Set() });
    }
    this.prefixWatchers.get(prefixStr)!.handlers.add(handler);

    try {
      while (!options?.signal?.aborted && !this.closed) {
        if (eventQueue.length === 0) {
          let timeoutId: ReturnType<typeof setTimeout> | undefined;
          await Promise.race([
            new Promise<void>((resolve) => {
              resolveNext = resolve;
            }),
            new Promise<void>((resolve) => {
              timeoutId = setTimeout(resolve, options?.pollInterval ?? 1000);
            }),
          ]);
          if (timeoutId !== undefined) {
            clearTimeout(timeoutId);
          }
        }

        while (eventQueue.length > 0) {
          const event = eventQueue.shift()!;
          if (options?.debounce && !(await this.debounce(options.debounce, options.signal))) {
            return;
          }
          yield event;
        }
      }
    } finally {
      const entry = this.prefixWatchers.get(prefixStr);
      if (entry) {
        entry.handlers.delete(handler);
        if (entry.handlers.size === 0) {
          this.prefixWatchers.delete(prefixStr);
        }
      }
    }
  }

  /**
   * Clear all entries from the in-memory store.
   */
  clear(): void {
    this.storage.clear();
  }

  /**
   * Get the current number of stored entries.
   */
  get size(): number {
    return this.storage.size;
  }

  /**
   * Get every stored key.
   *
   * @returns Snapshot of all keys in the adapter
   */
  keys(): KvKey[] {
    return Array.from(this.storage.values(), (entry) => entry.key);
  }

  /**
   * Wait out a watch debounce window, ending early when the watch is aborted.
   *
   * @param ms - Debounce window in milliseconds
   * @param signal - Watch abort signal
   * @returns `true` when the window elapsed, `false` when the watch was aborted
   */
  private async debounce(ms: number, signal?: AbortSignal): Promise<boolean> {
    try {
      await delay(ms, { signal });
      return true;
    } catch (error: unknown) {
      if (signal?.aborted) return false;
      throw error;
    }
  }

  /**
   * Apply one atomic mutation under the commit versionstamp.
   *
   * @param mutation - Mutation to apply
   * @param versionstamp - Versionstamp of the enclosing commit
   */
  private applyMutation(mutation: AtomicMutation, versionstamp: string): void {
    switch (mutation.type) {
      case 'set':
        this.writeEntry(mutation.key, mutation.value, versionstamp, mutation.expireIn);
        return;
      case 'delete':
        this.removeEntry(mutation.key, versionstamp);
        return;
      default: {
        const stored = this.liveEntry(keyToString(mutation.key))?.value;
        this.writeEntry(
          mutation.key,
          combineAtomicValue(mutation.type, stored, mutation.value),
          versionstamp,
        );
      }
    }
  }

  /**
   * Store an entry and notify watchers.
   *
   * @param key - Key to write
   * @param value - Value to store
   * @param versionstamp - Versionstamp of the write
   * @param expireIn - Optional TTL in milliseconds
   */
  private writeEntry(
    key: KvKey,
    value: unknown,
    versionstamp: string,
    expireIn?: number,
  ): void {
    const keyStr = keyToString(key);
    const existing = this.storage.get(keyStr);
    const entry: StorageEntry = {
      expiresAt: expireIn ? Date.now() + expireIn : undefined,
      key,
      value,
      versionstamp,
    };

    this.storage.set(keyStr, entry);

    if (entry.expiresAt) {
      this.expirationHeap.push({ expiresAt: entry.expiresAt, keyStr });
    }

    this.notifyWatchers(key, value, existing?.value ?? null, 'set', versionstamp);
  }

  /**
   * Remove an entry, if present, and notify watchers.
   *
   * @param key - Key to remove
   * @param versionstamp - Versionstamp of the deletion
   */
  private removeEntry(key: KvKey, versionstamp: string): void {
    const keyStr = keyToString(key);
    const existing = this.storage.get(keyStr);
    if (!existing) {
      return;
    }

    this.storage.delete(keyStr);
    this.notifyWatchers(key, null, existing.value, 'delete', versionstamp);
  }

  /**
   * Resolve a stored entry that has not expired.
   *
   * @param keyStr - Serialized key
   * @returns The live entry, or `undefined`
   */
  private liveEntry(keyStr: string): StorageEntry | undefined {
    const entry = this.storage.get(keyStr);
    if (entry?.expiresAt && entry.expiresAt <= Date.now()) {
      return undefined;
    }
    return entry;
  }

  /**
   * Ensure the adapter has not been closed.
   */
  private assertOpen(): void {
    if (this.closed) {
      throw new KvClosedError('MemoryKvAdapter is closed.');
    }
  }

  /**
   * Start the periodic expiration sweep.
   */
  private startExpirationChecker(): void {
    this.expirationTimer = setInterval(() => {
      const now = Date.now();

      while (this.expirationHeap.length > 0) {
        const top = this.expirationHeap.peek()!;
        if (top.expiresAt > now) break;
        this.expirationHeap.pop();

